result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_interp.py", "content": "import numpy as np
import pytest

from interp import (
    NaturalCubicSpline,
    chebyshev_nodes,
    equispaced_nodes,
    f,
    lagrange_eval,
)

GRID = np.linspace(-1.0, 1.0, 1001)
FGRID = f(GRID)


def lagrange_max_error(nodes):
    ys = f(nodes)
    return np.max(np.abs(lagrange_eval(nodes, ys, GRID) - FGRID))


def spline_max_error(nodes):
    sp = NaturalCubicSpline(nodes, f(nodes))
    return np.max(np.abs(sp(GRID) - FGRID))


def test_lagrange_equispaced_11_blowup():
    """Runge phenomenon: 11 equispaced nodes -> error explodes above 1.5."""
    err = lagrange_max_error(equispaced_nodes(11))
    assert err > 1.5


def test_spline_equispaced_11_beats_lagrange():
    """Natural cubic spline with the same nodes stays below 0.03."""
    assert spline_max_error(equispaced_nodes(11)) < 0.03


def test_lagrange_chebyshev_11_tames_runge():
    """Chebyshev-node Lagrange interpolation drops below 0.11 error."""
    assert lagrange_max_error(chebyshev_nodes(11)) < 0.11


def test_spline_equispaced_21_refines():
    """Doubling node density: spline max error under 0.004."""
    assert spline_max_error(equispaced_nodes(21)) < 0.004


@pytest.mark.parametrize("n", [3, 5, 8, 11, 21, 41, 101])
def test_spline_interpolates_exactly_at_nodes(n):
    for nodes in (equispaced_nodes(n), chebyshev_nodes(n)):
        ys = f(nodes)
        sp = NaturalCubicSpline(nodes, ys)
        assert np.max(np.abs(sp(nodes) - ys)) < 1e-12


@pytest.mark.parametrize(
    "nodes",
    [equispaced_nodes(n) for n in (4, 7, 11, 16, 21)]
    + [chebyshev_nodes(n) for n in (4, 7, 11, 21)],
    ids=lambda nd: f"{len(nd)}-nodes",
)
def test_matches_scipy_natural(nodes):
    from scipy.interpolate import CubicSpline

    ys = f(nodes)
    ours = NaturalCubicSpline(nodes, ys)(GRID)
    ref = CubicSpline(np.asarray(nodes), ys, bc_type="natural")(GRID)
    assert np.max(np.abs(ours - ref)) < 1e-10
